// ---- js/hud.js ----
__def("js/hud", function (__exports, __require) {
// Debug HUD — PLAN.md §1.2 verification surface: per-body measured angle vs the
// expected t/T, sun radius, active flags, event log, GPU/renderer info, fps.
// Plain DOM, updated at ~4 Hz (never per frame), zero allocation in the loop.

const VALUE_COLOR = '#7ee787';
const WARN_COLOR = '#ff7b72';

function createHud({ mount, world }) {
  const root = document.createElement('div');
  root.id = 'ow-hud';
  mount.appendChild(root);

  const head = document.createElement('div');
  head.className = 'ow-hud-head';
  root.appendChild(head);

  const table = document.createElement('table');
  table.className = 'ow-hud-table';
  const tbody = document.createElement('tbody');
  table.appendChild(tbody);
  root.appendChild(table);

  const foot = document.createElement('div');
  foot.className = 'ow-hud-foot';
  root.appendChild(foot);

  // Preallocated rows: id, θmeasured, θexpected, Δ, period, variant
  const tracked = world.nodes.filter((n) => n.kind === 'circle' && n.parent && !n.virtual);
  const rows = tracked.map((n) => {
    const tr = document.createElement('tr');
    const cells = [];
    for (let i = 0; i < 5; i++) {
      const td = document.createElement('td');
      tr.appendChild(td);
      cells.push(td);
    }
    cells[0].textContent = n.id;
    tbody.appendChild(tr);
    return { node: n, cells };
  });

  const log = [];
  let lastUpdate = -1;
  // Two different rates matter: how often the loop ticks, and how often a frame is
  // actually drawn (the loop deliberately skips draws when idle — PLAN.md §1.2).
  let loopFps = 0, drawFps = 0, ticks = 0, draws0 = 0, t0 = -1;
  let gpuInfo = 'pending';
  let visible = true;

  const norm = (a) => { let d = a; while (d > Math.PI) d -= 2 * Math.PI; while (d < -Math.PI) d += 2 * Math.PI; return d; };

  const hud = {
    root,
    setVisible(v) { visible = v; root.style.display = v ? '' : 'none'; },
    setWorld(next) {
      world = next;
      for (const row of rows) row.node = next.nodeById.get(row.node.id);
      log.length = 0;
      lastUpdate = -1;
    },
    get visible() { return visible; },
    setGpuInfo(s) { gpuInfo = s; },
    tick(frame, camera, stats) {
      // rates over real time (a paused or resyncing clock must not fake them)
      const now = performance.now() / 1000;
      if (t0 < 0) { t0 = now; draws0 = stats?.draws ?? 0; }
      ticks++;
      const elapsed = now - t0;
      if (elapsed >= 1) {
        loopFps = ticks / elapsed;
        drawFps = ((stats?.draws ?? 0) - draws0) / elapsed;
        ticks = 0; draws0 = stats?.draws ?? 0; t0 = now;
      }
      if (!visible || now - lastUpdate < 0.25) return;
      lastUpdate = now;

      const scale = frame.scaleParams;
      head.textContent =
        `t = ${frame.t.toFixed(2)}s / ${frame.cycleS}s  ·  loop ${loopFps.toFixed(0)}/s  ·  draw ${drawFps.toFixed(0)}/s` +
        `  (${stats?.drawCalls ?? '-'} calls, ${(stats?.lastMs ?? 0).toFixed(2)} ms)` +
        `  ·  map p=${scale.p.toFixed(2)} kLocal=${scale.kLocal} kBody=${scale.kBody}${scale.realScale ? ' REAL SCALE' : ''}`;

      for (const r of rows) {
        const n = r.node;
        const p = n.parent ? world.nodeById.get(n.parent) : null;
        const i = world.ids.indexOf(n.id);
        const b = frame.bodies[i];
        const measured = Math.atan2(b.z - (p ? p.z : 0), b.x - (p ? p.x : 0));
        const expected = n.phaseRad + (Number.isFinite(n.periodS) ? (2 * Math.PI * frame.t) / n.periodS : 0);
        const d = norm(measured - expected);
        r.cells[1].textContent = ((measured * 180) / Math.PI).toFixed(1) + '°';
        r.cells[2].textContent = (((expected * 180) / Math.PI) % 360).toFixed(1) + '°';
        r.cells[3].textContent = (d * 1e6).toFixed(1) + 'e-6';
        r.cells[3].style.color = Math.abs(d) < 1e-6 ? VALUE_COLOR : WARN_COLOR;
        r.cells[4].textContent = `${n.periodS.toFixed(2)}s · ${b.variant}${b.visible ? '' : ' · hidden'}`;
      }

      const f = frame.flags;
      foot.innerHTML = [
        `sun R ${frame.sun.realRadius.toFixed(0)} m → ${frame.sun.visualRadius.toFixed(0)} vis (mix ${frame.sun.mix.toFixed(2)}, flash ${frame.sun.flash.toFixed(2)})`,
        `station opacity ${frame.sunStation.opacity.toFixed(2)}`,
        `sand ${f.sandFlowing ? 'on' : 'off'} · ice ${f.iceOpen ? 'open' : 'closed'} · crater ${f.craterLevel}/5`,
        `stranger ${f.strangerSails ? 'sails' : 'cloaked'} · probe ${f.probeLaunched ? 'launched' : 'docked'} · star extinction ${(f.starExtinction * 100).toFixed(0)}%`,
        `particles ${frame.particleCount}`,
        `event  ${log.length ? log[log.length - 1] : '—'}`,
        `gpu    ${gpuInfo}`,
        `keys   drag=rotate · wheel=zoom · middle drag=pan（H/P/R 仅浏览器内可用：WE 不转发键盘）`,
      ].join('<br>');
    },
    pushEvent(e, t) {
      log.push(`[${t.toFixed(1)}s] ${e.label} (${e.tolerance}/${e.source})`);
      if (log.length > 6) log.shift();
    },
  };
  return hud;
}

__exports.createHud = createHud;
});


// ---- js/lib/framerate.js ----
__def("js/lib/framerate", function (__exports, __require) {
// Frame pacing — PLAN.md §1.2 (挂机开销低) and §4.4 (fpsLimit / idleFps).
//
// The loop ticks on every animation frame (cheap: sample + HUD), but only *draws* are
// paced. `busy` (interaction, particles, supernova flash) raises the cap to `fpsLimit`;
// it must never remove the cap — an uncapped "busy" branch is exactly how a wallpaper
// ends up drawing at the compositor rate forever.
//
// Pure numbers only, so the rule is testable without a GL context or a DOM.

/** Seconds that must elapse between two draws for the given state. */
function drawIntervalS(busy, fpsLimit, idleFps) {
  const fps = busy ? fpsLimit : idleFps;
  return 1 / Math.max(1, Number(fps) || 0);
}

/** True when a frame is due. `lastDrawS` may be -Infinity so the first frame draws at once. */
function drawDue(nowS, lastDrawS, busy, fpsLimit, idleFps) {
  return nowS - lastDrawS >= drawIntervalS(busy, fpsLimit, idleFps);
}

__exports.drawIntervalS = drawIntervalS;
__exports.drawDue = drawDue;
});


// ---- js/lib/playback.js ----
__def("js/lib/playback", function (__exports, __require) {
// Coalesce host pause, page visibility and context loss. No DOM dependencies.
function createPlayback({ clock, now, rate = () => 1, silentGapS = 1 }) {
  const reasons = new Set();
  let last = now(), suspendedAt = 0, dt = 0;
  return {
    get suspended() { return reasons.size > 0; },
    get dt() { return dt; },
    setSuspended(reason, value) {
      const was = reasons.size > 0;
      if (value) reasons.add(reason); else reasons.delete(reason);
      const active = reasons.size > 0;
      if (active === was) return;
      const stamp = now();
      if (active) { suspendedAt = stamp; clock.setHidden(true); }
      else { clock.setHidden(false, Math.max(0, stamp - suspendedAt), rate()); }
      last = stamp; dt = 0;
    },
    advance(stamp = now()) {
      const elapsed = Math.max(0, stamp - last);
      last = stamp;
      dt = Math.min(elapsed, 0.25);
      if (reasons.size) { dt = 0; return 0; }
      // Some hosts suspend rAF without a visibility/host notification.
      if (elapsed > silentGapS) {
        const before = clock.wraps;
        clock.setHidden(true);
        clock.setHidden(false, elapsed, rate());
        dt = 0;
        return clock.wraps - before;
      }
      return clock.advance(elapsed, rate());
    },
  };
}

__exports.createPlayback = createPlayback;
});


// ---- js/lib/props.js ----
__def("js/lib/props", function (__exports, __require) {
// Wallpaper Engine user-property bridge — PLAN.md §4.4 / §3.7.
//
// Two facts drive this module:
//   1. WE lower-cases every property name before it reaches `applyUserProperties`
//      (`project.json` says `fpslimit`, the scene's field is `fpsLimit`), so a naive
//      `if (key in props)` check silently drops almost every setting.
//   2. WE sliders/combo/colour values arrive as strings often enough that numbers
//      must be coerced, otherwise `dt * props.timeScale` turns into NaN.
//
// Pure: no DOM, no globals, so the mapping is unit-tested (test/props.test.mjs).

function createProps(defaults, rules = {}) {
  const props = { ...defaults };
  const byLowerName = new Map(Object.keys(props).map((k) => [k.toLowerCase(), k]));

  return {
    props,

    /** Name of the field a WE property key maps to, or null when unknown. */
    fieldOf(rawKey) {
      return byLowerName.get(String(rawKey).toLowerCase()) ?? null;
    },

    /**
     * Apply one WE `applyUserProperties` batch. Returns the list of the scene fields
     * that actually changed, so the caller can rebuild only what it must.
     */
    apply(updates) {
      const changed = [];
      if (!updates) return changed;
      for (const rawKey of Object.keys(updates)) {
        const field = byLowerName.get(String(rawKey).toLowerCase());
        if (!field) continue;
        const value = updates[rawKey]?.value;
        if (value === undefined) continue;
        const current = props[field];
        let next;
        if (typeof current === 'boolean') {
          if (value === true || value === 1 || value === 'true' || value === '1') next = true;
          else if (value === false || value === 0 || value === 'false' || value === '0') next = false;
          else continue;
        }
        else if (typeof current === 'number') {
          if ((typeof value !== 'number' && typeof value !== 'string') || String(value).trim() === '') continue;
          next = Number(value);
          if (!Number.isFinite(next)) continue;
        } else {
          if (typeof value !== 'string') continue;
          next = value;
        }
        const rule = rules[field];
        if (rule?.values && !rule.values.includes(next)) continue;
        if (typeof next === 'number' && rule) next = Math.min(rule.max ?? Infinity, Math.max(rule.min ?? -Infinity, next));
        if (next === current) continue;
        props[field] = next;
        changed.push(field);
      }
      return changed;
    },
  };
}

__exports.createProps = createProps;
});


