  hot: [255, 138, 64],
  interior: [46, 34, 30],
  storm: [180, 92, 68],
  spore: [206, 222, 255],
  sail: [214, 232, 238],
  sailEdge: [170, 255, 224],
  white: [255, 255, 255],
